39	// Description:
40	//   This file defines the Control and Status Registers (CSR)
41	//==========================================================================
42	
43	addrmap csr {
44	   name = "csr";
45	   desc = "WireGuard FPGA CSR";
46	
47	   littleendian;
48	   default accesswidth = 32;
49	   default regwidth = 32;
50	   default alignment = 4;
51	   addressing = compact;
52	
53	   regfile cpu_fifo {
54	      name = "csr.cpu_fifo";
55	      desc = "CPU FIFOs CSR";
56	
57	      regfile rx {
58	         name = "csr.cpu_fifo.rx";
59	         desc = "Rx FIFO CSR (CPU --> DPE)";
60	
61	         reg {
62	            name = "csr.cpu_fifo.rx.data_31_0";
63	            desc = "Rx FIFO Data Register";
64	
65	            field {
66	               name = "csr.cpu_fifo.rx.data_31_0.tdata[31:0]";
67	               desc = "1st 4-byte segment of TDATA, i.e. TDATA[31:0]";
68	               sw = rw;
69	               hw = r;
70	            } tdata[32] = 0;
71	         } data_31_0;
72	
73	         reg {
74	            name = "csr.cpu_fifo.rx.data_63_32";
75	            desc = "Rx FIFO Data Register";
76	
77	            field {
78	               name = "csr.cpu_fifo.rx.data_63_32.tdata[31:0]";
79	               desc = "2nd 4-byte segment of TDATA, i.e. TDATA[63:32]";
80	               sw = rw;
81	               hw = r;
82	            } tdata[32] = 0;
83	         } data_63_32;
84	
85	         reg {
86	            name = "csr.cpu_fifo.rx.data_95_64";
87	            desc = "Rx FIFO Data Register";
88	
89	            field {
90	               name = "csr.cpu_fifo.rx.data_95_64.tdata[31:0]";
91	               desc = "3rd 4-byte segment of TDATA, i.e. TDATA[95:64]";
92	               sw = rw;
93	               hw = r;
94	            } tdata[32] = 0;
95	         } data_95_64;
96	
97	         reg {
98	            name = "csr.cpu_fifo.rx.data_127_96";
99	            desc = "Rx FIFO Data Register";
100	
101	            field {
102	                name = "csr.cpu_fifo.rx.data_127_96.tdata[31:0]";
103	               desc = "4th 4-byte segment of TDATA, i.e. TDATA[127:96]";
104	               sw = rw;
105	               hw = r;
106	            } tdata[32] = 0;
107	         } data_127_96;
108	
109	         reg {
110	            name = "csr.cpu_fifo.rx.control";
111	            desc = "Rx FIFO Control Register";
112	
113	            field {
114	               name = "csr.cpu_fifo.rx.control.tkeep[15:0]";
115	               desc = "Byte-enable for TDATA (e.g. TKEEP[15] corresponds to TDATA[127:119])";
116	               sw = rw;
117	               hw = r;
118	            } tkeep[31:16] = 0;
119	
120	            field {
121	               name = "csr.cpu_fifo.rx.control.tlast";
122	               desc = "Indicates boundary of a packet, i.e. active on last transfer";
123	               sw = rw;
124	               hw = r;
125	            } tlast[15:15] = 0;
126	
127	            field {
128	               name = "csr.cpu_fifo.rx.control.tuser_bypass_all";
129	               desc = "DPE is bypassed when active";
130	               sw = rw;
131	               hw = r;
132	            } tuser_bypass_all[7:7] = 0;
133	
134	            field {
135	               name = "csr.cpu_fifo.rx.control.tuser_bypass_stage";
136	               desc = "Next stage of the DPE is bypassed when active";
137	               sw = rw;
138	               hw = r;
139	            } tuser_bypass_stage[6:6] = 0;
140	
141	            field {
142	               name = "csr.cpu_fifo.rx.control.tuser_src[2:0]";
143	               desc = "Internal source address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4)";
144	               sw = rw;
145	               hw = r;
146	            } tuser_src[5:3] = 0;
147	
148	            field {
149	               name = "csr.cpu_fifo.rx.control.tuser_dst[2:0]";
150	               desc = "Internal destination address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4, 7 - broadcast)";
151	               sw = rw;
152	               hw = r;
153	            } tuser_dst[2:0] = 0;
154	         } control;
155	
156	         reg {
157	            name = "csr.cpu_fifo.rx.trigger";
158	            desc = "Rx FIFO Trigger Register";
159	
160	            field {
161	               name = "csr.cpu_fifo.rx.trigger.tvalid";
162	               desc = "Indicates valid transfer from the CPU to the Rx FIFO (single pulse trigger)";
163	               singlepulse = true;
164	               sw = rw;
165	               hw = r;
166	            } tvalid = 0;
167	         } trigger;
168	
169	         reg {
170	            name = "csr.cpu_fifo.rx.status";
171	            desc = "Rx FIFO Status Register";
172	
173	            field {
174	               name = "csr.cpu_fifo.rx.status.tready";
175	               desc = "Indicates that the Rx FIFO can accept a transfer";
176	               sw = r;
177	               hw = w;
178	            } tready = 0;
179	         } status;
180	      } rx;
181	
182	      regfile tx {
183	         name = "csr.cpu_fifo.tx";
184	         desc = "Tx FIFO CSR (DPE --> CPU)";
185	
186	         reg {
187	            name = "csr.cpu_fifo.tx.data_31_0";
188	            desc = "Tx FIFO Data Register";
189	
190	            field {
191	               name = "csr.cpu_fifo.tx.data_31_0.tdata[31:0]";
192	               desc = "1st 4-byte segment of TDATA, i.e. TDATA[31:0]";
193	               sw = r;
194	               hw = w;
195	            } tdata[32] = 0;
196	         } data_31_0;
197	
198	         reg {
199	            name = "csr.cpu_fifo.tx.data_63_32";
200	            desc = "Tx FIFO Data Register";
201	
202	            field {
203	               name = "csr.cpu_fifo.tx.data_63_32.tdata[31:0]";
204	               desc = "2nd 4-byte segment of TDATA, i.e. TDATA[63:32]";
205	               sw = r;
206	               hw = w;
207	            } tdata[32] = 0;
208	         } data_63_32;
209	
210	         reg {
211	            name = "csr.cpu_fifo.tx.data_95_64";
212	            desc = "Tx FIFO Data Register";
213	
214	            field {
215	               name = "csr.cpu_fifo.tx.data_95_64.tdata[31:0]";
216	               desc = "3rd 4-byte segment of TDATA, i.e. TDATA[95:64]";
217	               sw = r;
218	               hw = w;
219	            } tdata[32] = 0;
220	         } data_95_64;
221	
222	         reg {
223	            name = "csr.cpu_fifo.tx.data_127_96";
224	            desc = "Tx FIFO Data Register";
225	
226	            field {
227	               name = "csr.cpu_fifo.tx.data_127_96.tdata[31:0]";
228	               desc = "4th 4-byte segment of TDATA, i.e. TDATA[127:96]";
229	               sw = r;
230	               hw = w;
231	            } tdata[32] = 0;
232	         } data_127_96;
233	
234	         reg {
235	            name = "csr.cpu_fifo.tx.control";
236	            desc = "Tx FIFO Control Register";
237	
238	            field {
239	               name = "csr.cpu_fifo.tx.control.tkeep[15:0]";
240	               desc = "Byte-enable for TDATA (e.g. TKEEP[15] corresponds to TDATA[127:119])";
241	               sw = r;
242	               hw = w;
243	            } tkeep[31:16] = 0;
244	
245	            field {
246	               name = "csr.cpu_fifo.tx.control.tlast";
247	               desc = "Indicates boundary of a packet, i.e. active on last transfer";
248	               sw = r;
249	               hw = w;
250	            } tlast[15:15] = 0;
251	
252	            field {
253	               name = "csr.cpu_fifo.tx.control.tuser_bypass_all";
254	               desc = "If active, DPE was bypassed";
255	               sw = r;
256	               hw = w;
257	            } tuser_bypass_all[7:7] = 0;
258	
259	            field {
260	               name = "csr.cpu_fifo.tx.control.tuser_bypass_stage";
261	               desc = "If active, last stage of the DPE was bypassed";
262	               sw = r;
263	               hw = w;
264	            } tuser_bypass_stage[6:6] = 0;
265	
266	            field {
267	               name = "csr.cpu_fifo.tx.control.tuser_src[2:0]";
268	               desc = "Internal source address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4)";
269	               sw = r;
270	               hw = w;
271	            } tuser_src[5:3] = 0;
272	
273	            field {
274	               name = "csr.cpu_fifo.tx.control.tuser_dst[2:0]";
275	               desc = "Internal destination address (0 - CPU, 1 - eth1, 2 - eth2, 3 - eth3, 4 - eth4, 7 - broadcast)";
276	               sw = r;
277	               hw = w;
278	            } tuser_dst[2:0] = 0;
279	         } control;
280	
281	         reg {
282	            name = "csr.cpu_fifo.tx.trigger";
283	            desc = "Tx FIFO Trigger Register";
284	
285	            field {
286	               name = "csr.cpu_fifo.tx.trigger.tready";
287	               desc = "Indicates that the CPU can accept a transfer";
288	               singlepulse = true;
289	               sw = rw;
290	               hw = r;
291	            } tready = 0;
292	         } trigger;
293	
294	         reg {
295	            name = "csr.cpu_fifo.tx.status";
296	            desc = "Tx FIFO Status Register";
297	
298	            field {
299	               name = "csr.cpu_fifo.tx.status.tvalid";
300	               desc = "Indicates valid transfer from the Tx FIFO to the CPU";
301	               sw = r;
302	               hw = w;
303	            } tvalid = 0;
304	         } status;
305	      } tx;
306	   } cpu_fifo;
307	
308	   regfile uart {
309	      name = "csr.uart";
310	      desc = "UART CSR";
311	
312	      reg {
313	         name = "csr.uart.rx";
314	         desc = "UART Rx Register";
315	
316	         field {
317	            name = "csr.uart.rx.valid";
318	            desc = "Indicates valid data transfer from the UART to the CPU";
319	            sw = r;
320	            hw = w;
321	         } valid[31:31] = 0;
322	
323	         field {
324	            name = "csr.uart.rx.oflow";
325	            desc = "Indicates that some data bytes are lost";
326	            sw = r;
327	            hw = w;
328	         } oflow[30:30] = 0;
329	
