int heap_memory_used = 0;

void* malloc(int size) {
   char* p = heap_memory + heap_memory_used;
   heap_memory_used += size;
   if (heap_memory_used > 32768)
      asm volatile ("ebreak");
   return p;
}

void* operator new(unsigned int size) {
   return malloc(size);
}

